"use strict";const e=require("../utils/request.js");exports.fetchBudgetReminderStatus=function(){return e.http.get("/budget-reminders",{noLedger:!0})},exports.grantBudgetReminderQuota=function(t){return e.http.post("/budget-reminders/quota:grant",{grantedCount:t},{noLedger:!0})},exports.updateBudgetReminderPreference=function(t){return e.http.put("/budget-reminders/preference",{enabled:t},{noLedger:!0})};
